/* ACP · AW chart hover (externalisé du body AW pour la place). window.ACP_AWHOVER(host,dates,series,lo,hi) */
window.ACP_AWHOVER=function(host,dates,series,lo,hi){
 var cc=host.querySelector(".chart-container");
 if(!cc||!dates||dates.length<2)return;
 var W=900,H=320,L=48,RW=842,TP=10,PH=280;
 var ov=document.createElement("div");
 ov.style.cssText="position:absolute;inset:0;pointer-events:none;z-index:6";
 var vl=document.createElement("div");
 vl.style.cssText="position:absolute;width:1px;background:rgba(245,230,200,.45);opacity:0;transition:opacity .08s";
 ov.appendChild(vl);
 var dots=series.map(function(sr){ var d=document.createElement("div"); d.style.cssText="position:absolute;width:8px;height:8px;border-radius:50%;background:"+sr.color+";border:2px solid #0b1628;transform:translate(-50%,-50%);opacity:0"; ov.appendChild(d); return d; });
 var tip=document.createElement("div");
 tip.style.cssText="position:absolute;top:8px;background:#132240;border:1px solid #1e3155;border-radius:6px;padding:7px 10px;font-family:'JetBrains Mono',monospace;white-space:nowrap;opacity:0;transition:opacity .08s;box-shadow:0 6px 20px rgba(0,0,0,.4);z-index:7";
 ov.appendChild(tip);
 cc.appendChild(ov);
 function px(i){ return (L+i/(dates.length-1)*RW)/W; }
 function py(v){ return (TP+PH*(1-(v-lo)/(hi-lo)))/H; }
 function fmtDate(x){ var p=String(x).split("-"); return p.length===3?p[2]+"/"+p[1]+"/"+p[0]:x; }
 function move(ev){
 var r=cc.getBoundingClientRect(); if(!r.width)return;
 var fx=(ev.clientX-r.left)/r.width;
 var idx=Math.round((fx*W-L)/RW*(dates.length-1));
 if(idx<0)idx=0; if(idx>dates.length-1)idx=dates.length-1;
 var xpx=px(idx)*r.width;
 vl.style.left=xpx+"px"; vl.style.top=(TP/H*r.height)+"px"; vl.style.height=(PH/H*r.height)+"px"; vl.style.opacity="1";
 var html='<div style="font-size:11px;font-weight:600;color:#f5e6c8;margin-bottom:3px">'+fmtDate(dates[idx])+'</div>';
 series.forEach(function(sr,si){
 var v=sr.data[idx];
 if(v==null||isNaN(v)){ dots[si].style.opacity="0"; }
 else{ dots[si].style.left=xpx+"px"; dots[si].style.top=(py(v)*r.height)+"px"; dots[si].style.opacity="1";
 html+='<div style="font-size:10px;color:'+sr.color+'">'+sr.label+': '+v.toFixed(1)+'</div>'; }
 });
 tip.innerHTML=html; tip.style.opacity="1";
 var tw=tip.offsetWidth||130, lft=xpx+14;
 if(lft+tw>r.width-4)lft=xpx-tw-14; if(lft<4)lft=4;
 tip.style.left=lft+"px";
 }
 function leave(){ vl.style.opacity="0"; dots.forEach(function(d){d.style.opacity="0";}); tip.style.opacity="0"; }
 cc.addEventListener("mousemove",move);
 cc.addEventListener("mouseleave",leave);
 cc.addEventListener("touchmove",function(ev){ if(ev.touches&&ev.touches[0])move(ev.touches[0]); },{passive:true});
 cc.addEventListener("touchend",leave);
 };
